CREATE DATABASE roguelitee;
USE roguelitee;
CREATE TABLE Eventos (id SMALLINT PRIMARY KEY, cadenaTextoEvento VARCHAR(400) NOT NULL, idEventos VARCHAR(40) NOT NULL, idObjetos VARCHAR(40), cantidadCordura SMALLINT, cantidadCarisma SMALLINT, cantidadIntimidacion SMALLINT, cantidadInteligencia SMALLINT, cantidadSuerte SMALLINT);
